class Solution {
    pair<int, vector<int>> bfs(int source, const vector<vector<int>>& adj) {
        int n = adj.size();
        vector<int> dist(n, -1);
        queue<int> q;
        q.push(source);
        dist[source] = 0;
        int far = source;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            if (dist[u] > dist[far]) far = u;
            for (int v : adj[u]) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    q.push(v);
                }
            }
        }
        return {far, dist};
    }
public:
    vector<int> lastMarkedNodes(vector<vector<int>>& edges) {
        int n = edges.size() + 1;
        vector<vector<int>> adj(n);
        for (auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }
        int a = bfs(0, adj).first;
        auto fromA = bfs(a, adj);
        int b = fromA.first;
        auto fromB = bfs(b, adj);
        vector<int> ans(n);
        for (int i = 0; i < n; ++i) {
            ans[i] = fromA.second[i] >= fromB.second[i] ? a : b;
        }
        return ans;
    }
};
